// Signs release builds with your own upload key when one is provided.
//
// android/ is generated by `expo prebuild`, so the signing config is patched in
// here rather than edited by hand. Provide the key as Gradle properties — in CI
// via environment variables, e.g. ORG_GRADLE_PROJECT_LOCATIONMAP_STORE_FILE:
//
//   LOCATIONMAP_STORE_FILE      absolute path to the .jks / .keystore
//   LOCATIONMAP_STORE_PASSWORD
//   LOCATIONMAP_KEY_ALIAS
//   LOCATIONMAP_KEY_PASSWORD
//
// Without them the release APK falls back to the template's debug key, which
// is public: fine for trying the app, not for anything you distribute.
const { withAppBuildGradle } = require('expo/config-plugins');

const RELEASE_SIGNING_CONFIG = `
        release {
            if (findProperty('LOCATIONMAP_STORE_FILE')) {
                storeFile file(findProperty('LOCATIONMAP_STORE_FILE'))
                storePassword findProperty('LOCATIONMAP_STORE_PASSWORD')
                keyAlias findProperty('LOCATIONMAP_KEY_ALIAS')
                keyPassword findProperty('LOCATIONMAP_KEY_PASSWORD')
            }
        }`;

const DEBUG_SIGNING_CONFIG = /(signingConfigs \{\s*debug \{[^}]*\})/;
const RELEASE_BUILD_TYPE_SIGNING = /(release \{\s*(?:\/\/[^\n]*\n\s*)*)signingConfig signingConfigs\.debug/;

function patch(gradle) {
  if (gradle.includes("findProperty('LOCATIONMAP_STORE_FILE')")) return gradle;

  if (!DEBUG_SIGNING_CONFIG.test(gradle) || !RELEASE_BUILD_TYPE_SIGNING.test(gradle)) {
    throw new Error(
      'withReleaseSigning: app/build.gradle no longer matches the expected template; update the plugin.',
    );
  }

  return gradle
    .replace(DEBUG_SIGNING_CONFIG, `$1${RELEASE_SIGNING_CONFIG}`)
    .replace(
      RELEASE_BUILD_TYPE_SIGNING,
      "$1signingConfig findProperty('LOCATIONMAP_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
    );
}

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning: expected a Groovy app/build.gradle.');
    }
    mod.modResults.contents = patch(mod.modResults.contents);
    return mod;
  });

module.exports = withReleaseSigning;
module.exports.patch = patch;
